candidates.raw:
int config_ok = 1;
int input_ok;
int rejected = 0;
int primed_cycle = 0;
int was_initialized = 0;
adcs_bdot_state_t trial_filter;
adcs_vec3_t trial_rate = {0.0, 0.0, 0.0};
adcs_vec3_t dipole = {0.0, 0.0, 0.0};
unint32 sat_mask = 0U;
unint32 slew_mask = 0U;
double field_mag = 0.0;
double rate_norm = 0.0;
adcs_status_t st;

dt_output.mode = dt_state.mode;
dt_output.good = dt_state.good;
dt_output.bad = dt_state.bad;
dt_output.saturation_mask = 0U;
dt_output.slew_mask = 0U;
dt_output.filter_primed_this_cycle = 0;
dt_output.field_magnitude_t = 0.0;
dt_output.rate_norm_t_s = 0.0;
dt_output.rate_t_s = (adcs_vec3_t){0.0, 0.0, 0.0};
dt_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};

if (dt_input.enable != TRUE32) {
    dt_state.mode = DT_OFF;
    dt_state.good = 0U;
    dt_state.bad = 0U;
    dt_state.filter.initialized = 0;
    dt_state.filter.previous_field_t = (adcs_vec3_t){0.0, 0.0, 0.0};
    dt_state.filter.previous_time_s = 0.0;
    dt_state.filtered_rate_t_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    dt_output.mode = DT_OFF;
    dt_output.good = 0U;
    dt_output.bad = 0U;
    dt_output.saturation_mask = 0U;
    dt_output.slew_mask = 0U;
    dt_output.filter_primed_this_cycle = 0;
    dt_output.field_magnitude_t = 0.0;
    dt_output.rate_norm_t_s = 0.0;
    dt_output.rate_t_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

if ((dt_config.filter_alpha < 0.0) || (dt_config.filter_alpha > 1.0))
    config_ok = 0;
if ((dt_config.coarse_gain_a_m2_s_t < 0.0) || (dt_config.fine_gain_a_m2_s_t < 0.0))
    config_ok = 0;
if (!(dt_config.max_dipole_a_m2 > 0.0))
    config_ok = 0;
if (!(dt_config.max_dipole_slew_a_m2_per_cycle > 0.0))
    config_ok = 0;
if (!(dt_config.minimum_field_t > 0.0))
    config_ok = 0;
if (!(dt_config.maximum_field_t > 0.0))
    config_ok = 0;
if (!(dt_config.max_sample_gap_s > 0.0))
    config_ok = 0;
if ((dt_config.required_good < 1U) || (dt_config.required_good > 20U))
    config_ok = 0;
if ((dt_config.max_bad < 1U) || (dt_config.max_bad > 20U))
    config_ok = 0;
if (!(dt_config.stop_rate_t_s < dt_config.restart_rate_t_s))
    config_ok = 0;
if (!(dt_config.restart_rate_t_s <= dt_config.fine_enter_rate_t_s))
    config_ok = 0;
if (!(dt_config.fine_enter_rate_t_s < dt_config.fine_exit_rate_t_s))
    config_ok = 0;

input_ok = (dt_input.valid == TRUE32) && (dt_input.field_body_t != NULL) &&
           isfinite(dt_input.time_s);

if ((config_ok == 0) || (input_ok == 0))
    rejected = 1;

if (rejected == 0) {
    field_mag = adcs_vec3_norm(dt_input.field_body_t);
    if ((!isfinite(field_mag)) || (field_mag < dt_config.minimum_field_t) ||
        (field_mag > dt_config.maximum_field_t))
        rejected = 1;
}

if (rejected == 0) {
    was_initialized = dt_state.filter.initialized;
    trial_filter = dt_state.filter;
    if (trial_filter.initialized &&
        ((dt_input.time_s - trial_filter.previous_time_s) > dt_config.max_sample_gap_s)) {
        trial_filter.initialized = 0;
    }
    st = adcs_bdot_update(&trial_filter, dt_input.field_body_t, dt_input.time_s,
                          dt_config.filter_alpha, &trial_rate);
    if (st != ADCS_OK) {
        rejected = 1;
    } else if ((!was_initialized) || (trial_filter.initialized && was_initialized &&
                                      ((dt_input.time_s -
                                        dt_state.filter.previous_time_s) >
                                       dt_config.max_sample_gap_s))) {
        primed_cycle = 1;
    }
}

if (rejected == 0) {
    if (primed_cycle) {
        dt_state.filter = trial_filter;
        dt_state.mode = DT_COARSE;
        dt_state.good = 0U;
        dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
        dt_output.mode = DT_COARSE;
        dt_output.good = 0U;
        dt_output.filter_primed_this_cycle = 1;
        dt_output.rate_t_s = (adcs_vec3_t){0.0, 0.0, 0.0};
        dt_output.rate_norm_t_s = 0.0;
        dt_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
        dt_output.saturation_mask = 0U;
        dt_output.slew_mask = 0U;
        dt_output.field_magnitude_t = field_mag;
    } else {
        dt_state.filter = trial_filter;
        dt_state.filtered_rate_t_s = trial_rate;
        rate_norm = adcs_vec3_norm(&trial_rate);

        if (dt_state.mode == DT_COARSE) {
            if (rate_norm <= dt_config.fine_enter_rate_t_s)
                dt_state.mode = DT_FINE;
        } else if (dt_state.mode == DT_FINE) {
            if (rate_norm >= dt_config.fine_exit_rate_t_s)
                dt_state.mode = DT_COARSE;
        }

        if ((dt_state.mode == DT_COARSE) || (dt_state.mode == DT_FINE)) {
            if (rate_norm <= dt_config.stop_rate_t_s) {
                if (dt_state.good < dt_config.required_good)
                    dt_state.good++;
                if (dt_state.good >= dt_config.required_good)
                    dt_state.mode = DT_COMPLETE;
            } else {
                dt_state.good = 0U;
            }
        }

        if (dt_state.mode == DT_COMPLETE) {
            dipole = (adcs_vec3_t){0.0, 0.0, 0.0};
            sat_mask = 0U;
            slew_mask = 0U;
            dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
            if (rate_norm >= dt_config.fine_exit_rate_t_s) {
                dt_state.mode = DT_COARSE;
                dt_state.good = 0U;
            } else if (rate_norm >= dt_config.restart_rate_t_s) {
                dt_state.mode = DT_FINE;
                dt_state.good = 0U;
            }
        } else {
            double gain = (dt_state.mode == DT_COARSE) ? dt_config.coarse_gain_a_m2_s_t
                                                       : dt_config.fine_gain_a_m2_s_t;
            adcs_actuator_command_t cmd;
            cmd.command = (adcs_vec3_t){0.0, 0.0, 0.0};
            cmd.saturated_axes = 0U;
            st = adcs_bdot_dipole(dt_input.field_body_t, &trial_rate, gain,
                                  dt_config.max_dipole_a_m2, &cmd);
            if (st == ADCS_OK) {
                dipole = cmd.command;
                sat_mask = cmd.saturated_axes;
            } else {
                dipole = (adcs_vec3_t){0.0, 0.0, 0.0};
                sat_mask = 0U;
            }
            {
                double vals[3];
                double prev[3];
                size_t i;
                vals[0] = dipole.x;
                vals[1] = dipole.y;
                vals[2] = dipole.z;
                prev[0] = dt_state.previous_dipole_a_m2.x;
                prev[1] = dt_state.previous_dipole_a_m2.y;
                prev[2] = dt_state.previous_dipole_a_m2.z;
                for (i = 0; i < 3U; i++) {
                    double delta = vals[i] - prev[i];
                    if (delta > dt_config.max_dipole_slew_a_m2_per_cycle) {
                        vals[i] = prev[i] + dt_config.max_dipole_slew_a_m2_per_cycle;
                        slew_mask |= (unint32)(1U << i);
                    } else if (delta < -dt_config.max_dipole_slew_a_m2_per_cycle) {
                        vals[i] = prev[i] - dt_config.max_dipole_slew_a_m2_per_cycle;
                        slew_mask |= (unint32)(1U << i);
                    }
                    if (fabs(vals[i]) > dt_config.max_dipole_a_m2) {
                        vals[i] = copysign(dt_config.max_dipole_a_m2, vals[i]);
                        sat_mask |= (unint32)(1U << i);
                    }
                }
                dipole = (adcs_vec3_t){vals[0], vals[1], vals[2]};
            }
            dt_state.previous_dipole_a_m2 = dipole;
        }

        dt_output.mode = dt_state.mode;
        dt_output.good = dt_state.good;
        dt_output.rate_t_s = trial_rate;
        dt_output.rate_norm_t_s = rate_norm;
        dt_output.dipole_a_m2 = dipole;
        dt_output.saturation_mask = sat_mask;
        dt_output.slew_mask = slew_mask;
        dt_output.field_magnitude_t = field_mag;
    }
} else {
    dt_state.bad++;
    dt_state.good = 0U;
    if (dt_state.bad >= dt_config.max_bad)
        dt_state.mode = DT_FAULT;
    dt_output.mode = dt_state.mode;
    dt_output.good = 0U;
    dt_output.bad = dt_state.bad;
    dt_output.saturation_mask = 0U;
    dt_output.slew_mask = 0U;
    dt_output.filter_primed_this_cycle = 0;
    dt_output.field_magnitude_t = 0.0;
    dt_output.rate_norm_t_s = 0.0;
    dt_output.rate_t_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
}

