adcs_vec3_t field, trial_rate, dipole_cmd;
adcs_bdot_state_t trial_filter;
adcs_actuator_command_t cmd;
double field_mag, rate_norm, dt_gap;
unint32 sat_mask, slew_mask;
int config_valid, sample_accepted, primed;

/* 每次调用执行：清默认输出 */
dt_output.mode = dt_state.mode;
dt_output.good = dt_state.good;
dt_output.bad = dt_state.bad;
dt_output.saturation_mask = 0U;
dt_output.slew_mask = 0U;
dt_output.filter_primed_this_cycle = 0;
dt_output.field_magnitude_t = 0.0;
dt_output.rate_norm_t_s = 0.0;
dt_output.rate_t_s = (adcs_vec3_t){0, 0, 0};
dt_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};

/* 配置与标志校验：非法按拒绝样本处理（不立刻 FAULT） */
if ((dt_input.enable != 1) || (dt_input.valid != 1) || (dt_input.field_body_t == NULL)) {
    config_valid = 0;
} else if ((dt_config.required_good < 1U) || (dt_config.required_good > 20U) ||
           (dt_config.max_bad < 1U) || (dt_config.max_bad > 20U)) {
    config_valid = 0;
} else if ((!isfinite(dt_config.filter_alpha)) || (dt_config.filter_alpha < 0.0) ||
           (dt_config.filter_alpha > 1.0)) {
    config_valid = 0;
} else if ((!isfinite(dt_config.coarse_gain_a_m2_s_t)) || (dt_config.coarse_gain_a_m2_s_t < 0.0) ||
           (!isfinite(dt_config.fine_gain_a_m2_s_t)) || (dt_config.fine_gain_a_m2_s_t < 0.0)) {
    config_valid = 0;
} else if ((!isfinite(dt_config.max_dipole_a_m2)) || (dt_config.max_dipole_a_m2 <= 0.0) ||
           (!isfinite(dt_config.max_dipole_slew_a_m2_per_cycle)) ||
           (dt_config.max_dipole_slew_a_m2_per_cycle <= 0.0)) {
    config_valid = 0;
} else if ((!isfinite(dt_config.minimum_field_t)) || (dt_config.minimum_field_t < 0.0) ||
           (!isfinite(dt_config.maximum_field_t)) ||
           (dt_config.maximum_field_t < dt_config.minimum_field_t)) {
    config_valid = 0;
} else if ((!isfinite(dt_config.max_sample_gap_s)) || (dt_config.max_sample_gap_s <= 0.0)) {
    config_valid = 0;
} else if ((dt_config.stop_rate_t_s < 0.0) ||
           (dt_config.restart_rate_t_s <= dt_config.stop_rate_t_s) ||
           (dt_config.fine_enter_rate_t_s < dt_config.restart_rate_t_s) ||
           (dt_config.fine_exit_rate_t_s <= dt_config.fine_enter_rate_t_s)) {
    config_valid = 0;
} else {
    config_valid = 1;
}

/* 试算：在 filter 副本上做 */
field = *dt_input.field_body_t;
field_mag = adcs_vec3_norm(&field);
sample_accepted = 0;
trial_filter = dt_state.filter;
trial_rate = (adcs_vec3_t){0, 0, 0};
primed = trial_filter.initialized;

if (config_valid) {
    if ((field_mag >= dt_config.minimum_field_t) &&
        (field_mag <= dt_config.maximum_field_t)) {
        if (trial_filter.initialized) {
            dt_gap = dt_input.time_s - trial_filter.previous_time_s;
            if ((isfinite(dt_gap)) && (dt_gap > 0.0) &&
                (dt_gap <= dt_config.max_sample_gap_s)) {
                if (adcs_bdot_update(&trial_filter, &field, dt_input.time_s,
                                     dt_config.filter_alpha, &trial_rate) == ADCS_OK) {
                    sample_accepted = 1;
                    primed = 1;
                }
            } else {
                /* 超过 gap：reset and re-prime */
                trial_filter.initialized = 0;
                trial_rate = (adcs_vec3_t){0, 0, 0};
                if (adcs_bdot_update(&trial_filter, &field, dt_input.time_s,
                                     dt_config.filter_alpha, &trial_rate) == ADCS_OK) {
                    sample_accepted = 1;
                    primed = 0;
                }
            }
        } else {
            /* 首次样本 prime */
            if (adcs_bdot_update(&trial_filter, &field, dt_input.time_s,
                                 dt_config.filter_alpha, &trial_rate) == ADCS_OK) {
                sample_accepted = 1;
                primed = 0;
            }
        }
    }
}

/* 拒绝样本：保留 filter 与 previous dipole，发布零，清 good，bad++，达 max_bad 锁 FAULT */
if (!sample_accepted) {
    dt_state.good = 0;
    dt_state.bad += 1U;
    if (dt_state.bad >= dt_config.max_bad) {
        dt_state.mode = DT_FAULT;
    }
    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    dt_output.filter_primed_this_cycle = 0;
    dt_output.field_magnitude_t = 0.0;
    dt_output.rate_norm_t_s = 0.0;
    dt_output.rate_t_s = (adcs_vec3_t){0, 0, 0};
    dt_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    dt_output.saturation_mask = 0U;
    dt_output.slew_mask = 0U;
    return;
}

/* 接受：提交 filter 与速率 */
dt_state.filter = trial_filter;
dt_state.filtered_rate_t_s = trial_rate;
rate_norm = adcs_vec3_norm(&trial_rate);
dt_output.field_magnitude_t = field_mag;
dt_output.rate_norm_t_s = rate_norm;
dt_output.rate_t_s = trial_rate;

/* prime 或 re-prime 周期：COARSE，清 good，发布零速率与零偶极，置 filter_primed_this_cycle=1 */
if (!primed) {
    dt_state.mode = DT_COARSE;
    dt_state.good = 0;
    dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    dt_output.filter_primed_this_cycle = 1;
    dt_output.saturation_mask = 0U;
    dt_output.slew_mask = 0U;
    dt_output.rate_t_s = (adcs_vec3_t){0, 0, 0};
    dt_output.rate_norm_t_s = 0.0;
    dt_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    return;
}

sat_mask = 0U;
slew_mask = 0U;

/* 模式转移 */
if (dt_state.mode == DT_COMPLETE) {
    if (rate_norm >= dt_config.restart_rate_t_s) {
        if (rate_norm >= dt_config.fine_exit_rate_t_s) {
            dt_state.mode = DT_COARSE;
        } else {
            dt_state.mode = DT_FINE;
        }
        dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    }
} else if (dt_state.mode == DT_COARSE) {
    if (rate_norm <= dt_config.fine_enter_rate_t_s) {
        dt_state.mode = DT_FINE;
    }
} else if (dt_state.mode == DT_FINE) {
    if (rate_norm >= dt_config.fine_exit_rate_t_s) {
        dt_state.mode = DT_COARSE;
    }
}

/* good 计数与进入 COMPLETE（COARSE/FINE 活跃模式） */
if ((dt_state.mode == DT_COARSE) || (dt_state.mode == DT_FINE)) {
    if (rate_norm <= dt_config.stop_rate_t_s) {
        dt_state.good += 1U;
        if (dt_state.good >= dt_config.required_good) {
            dt_state.mode = DT_COMPLETE;
            dt_state.previous_dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
        }
    } else {
        dt_state.good = 0;
    }
}

/* COMPLETE：命令零 */
if (dt_state.mode == DT_COMPLETE) {
    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    dt_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    dt_output.saturation_mask = 0U;
    dt_output.slew_mask = 0U;
    return;
}

/* FAULT：命令零 */
if (dt_state.mode == DT_FAULT) {
    dt_output.mode = dt_state.mode;
    dt_output.good = dt_state.good;
    dt_output.bad = dt_state.bad;
    dt_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    dt_output.saturation_mask = 0U;
    dt_output.slew_mask = 0U;
    return;
}

/* 生成偶极并限幅 slew */
{
    double gain = (dt_state.mode == DT_FINE) ? dt_config.fine_gain_a_m2_s_t
                                             : dt_config.coarse_gain_a_m2_s_t;
    adcs_status_t dps = adcs_bdot_dipole(&field, &trial_rate, gain,
                                         dt_config.max_dipole_a_m2, &cmd);
    if (dps != ADCS_OK) {
        /* 生成失败按拒绝样本处理 */
        dt_state.mode = dt_state.mode;
        dt_state.good = 0;
        dt_state.bad += 1U;
        if (dt_state.bad >= dt_config.max_bad) {
            dt_state.mode = DT_FAULT;
        }
        dt_output.mode = dt_state.mode;
        dt_output.good = 0;
        dt_output.bad = dt_state.bad;
        dt_output.filter_primed_this_cycle = 0;
        dt_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
        dt_output.saturation_mask = 0U;
        dt_output.slew_mask = 0U;
        dt_output.rate_t_s = (adcs_vec3_t){0, 0, 0};
        dt_output.rate_norm_t_s = 0.0;
        return;
    }
    sat_mask = cmd.saturated_axes;
    {
        double dvx = cmd.command.x - dt_state.previous_dipole_a_m2.x;
        double dvy = cmd.command.y - dt_state.previous_dipole_a_m2.y;
        double dvz = cmd.command.z - dt_state.previous_dipole_a_m2.z;
        double lim = dt_config.max_dipole_slew_a_m2_per_cycle;
        double nx = cmd.command.x, ny = cmd.command.y, nz = cmd.command.z;
        if (fabs(dvx) > lim) {
            nx = dt_state.previous_dipole_a_m2.x + copysign(lim, dvx);
            slew_mask |= 1U;
        }
        if (fabs(dvy) > lim) {
            ny = dt_state.previous_dipole_a_m2.y + copysign(lim, dvy);
            slew_mask |= 2U;
        }
        if (fabs(dvz) > lim) {
            nz = dt_state.previous_dipole_a_m2.z + copysign(lim, dvz);
            slew_mask |= 4U;
        }
        dipole_cmd = (adcs_vec3_t){nx, ny, nz};
    }
}

dt_state.previous_dipole_a_m2 = dipole_cmd;
dt_output.mode = dt_state.mode;
dt_output.good = dt_state.good;
dt_output.bad = dt_state.bad;
dt_output.dipole_a_m2 = dipole_cmd;
dt_output.saturation_mask = sat_mask;
dt_output.slew_mask = slew_mask;
dt_output.filter_primed_this_cycle = 0;

