    adcs_vec3_t limited_dipole;
    adcs_bdot_state_t trial_filter;
    adcs_status_t upd_ok;
    adcs_status_t dip_ok;
    double field_mag;
    double rate_norm = 0.0;
    double gain;
    uint32_t sat_mask = 0U;
    uint32_t slew_mask = 0U;
    int reject_sample = 0;
    int re_prime = 0;

    if (!adcs_is_finite_vec3(&field_body_t)) reject_sample = 1;
    field_mag = adcs_vec3_norm(&field_body_t);
    if (field_mag < dt_config.minimum_field_t || field_mag > dt_config.maximum_field_t)
        reject_sample = 1;

    if (!reject_sample) {
        if (dt_state.filter.initialized == 0) {
            re_prime = 1;
        } else {
            double gap = dt_input.time_s - dt_state.filter.previous_time_s;
            if (!isfinite(gap) || gap <= 0.0) {
                reject_sample = 1;
            } else if (gap > dt_config.max_sample_gap_s) {
                re_prime = 1;
            } else {
                re_prime = 0;
            }
        }
